import GithubSlugger from 'github-slugger';
import {MarkdownLineBoundary} from './jsUtils';

// We create our own abstraction on top of the lib:
// - unify usage everywhere in the codebase
// - ability to add extra options
export type SluggerOptions = {
  /** Keep the headings' casing, otherwise make all lowercase. */
  maintainCase?: boolean;
};

export type Slugger = {
  /**
   * Takes a Markdown heading like "Josh Cena" and sluggifies it according to
   * GitHub semantics (in this case `josh-cena`). Stateful, because if you try
   * to sluggify "Josh Cena" again it would return `josh-cena-1`.
   */
  slug: (value: string, options?: SluggerOptions) => string;
};

/**
 * A thin wrapper around github-slugger. This is a factory function that returns
 * a stateful Slugger object.
 */
export function createSlugger(): Slugger {
  const githubSlugger = new GithubSlugger();
  return {
    slug: (value, options) => githubSlugger.slug(value, options?.maintainCase),
  };
}

/**
 * Describes an MDX fenced code block encountered while preprocessing Markdown.
 */
export class MdxCodeFence {
  private readonly marker: string;
  private readonly infoLabel: string;
  private readonly indentPattern: string;
  private readonly lineBoundary: MarkdownLineBoundary;

  constructor(backtickCount: number) {
    this.marker = '`'.repeat(backtickCount);
    this.infoLabel = 'mdx-code-block';
    this.indentPattern = '\\x20*';
    this.lineBoundary = new MarkdownLineBoundary();
  }

  getMarker(): string {
    return this.marker;
  }

  getInfoLabel(): string {
    return this.infoLabel;
  }

  getIndentPattern(): string {
    return this.indentPattern;
  }

  getLineBoundary(): MarkdownLineBoundary {
    return this.lineBoundary;
  }
}

